// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import org.eclipse.rdf4j.common.annotation.Experimental;

/** Loss-aware confidence controller for stale-generation Frontier plan validation. */
@Experimental
public final class FrontierDecisionRiskController {

	private static final double JEFFREYS_PRIOR_MASS = 1.0d;
	private static final double JEFFREYS_PRIOR_EXPECTED_REGRET = 0.5d;
	private static final double[] STANDARD_CONFIDENCE_TIERS = { 0.51d, 0.75d, 0.95d, 0.99d, 0.999d };

	private final Config config;
	private final Map<Long, AuditPosterior> families = new HashMap<>();
	private final Set<AuditIdentity> observedAudits = new HashSet<>();
	private long globalAuditCount;
	private long globalStableCount;
	private double globalRealizedRegret;

	public FrontierDecisionRiskController() {
		this(Config.defaults());
	}

	public FrontierDecisionRiskController(Config config) {
		this.config = config;
	}

	/** Records one independent audit; replaying the same audit lane and generation is idempotent. */
	public synchronized void observeAudit(long familyFingerprint, long auditIdentity, int auditLane, boolean stable,
			double realizedRegret) {
		if (auditLane < 0) {
			throw new IllegalArgumentException("Frontier audit lane must be nonnegative");
		}
		if (!Double.isFinite(realizedRegret) || realizedRegret < 0.0d) {
			throw new IllegalArgumentException("Frontier realized regret must be finite and nonnegative");
		}
		if (stable && realizedRegret != 0.0d) {
			throw new IllegalArgumentException("a stable Frontier audit cannot report execution regret");
		}
		AuditIdentity identity = new AuditIdentity(familyFingerprint, auditIdentity, auditLane);
		if (!observedAudits.add(identity)) {
			return;
		}
		AuditPosterior posterior = families.computeIfAbsent(familyFingerprint, ignored -> new AuditPosterior());
		posterior.auditCount++;
		globalAuditCount++;
		if (stable) {
			posterior.stableCount++;
			globalStableCount++;
		} else {
			posterior.realizedRegret += realizedRegret;
			globalRealizedRegret += realizedRegret;
		}
	}

	/**
	 * Chooses the evidence effort minimizing validation work plus posterior execution regret.
	 *
	 * <p>
	 * Confidence is family-wise: increasing the number of compared alternatives increases validation work via a
	 * Bonferroni allocation, while the configured regret bound continues to apply to the complete decision.
	 */
	public synchronized Decision select(long familyFingerprint, double winnerExecutionCost, double validationWork,
			int comparisonCount) {
		if (!Double.isFinite(winnerExecutionCost) || winnerExecutionCost <= 0.0d) {
			throw new IllegalArgumentException("winner execution cost must be finite and positive");
		}
		if (!Double.isFinite(validationWork) || validationWork < 0.0d) {
			throw new IllegalArgumentException("validation work must be finite and nonnegative");
		}
		if (comparisonCount <= 0) {
			throw new IllegalArgumentException("comparison count must be positive");
		}
		AuditPosterior local = families.get(familyFingerprint);
		double baseRegret = posteriorExpectedRegret(local);
		double instability = posteriorInstability(local);
		if (local == null || local.auditCount == 0L) {
			double expectedRegret = baseRegret * (1.0d - config.initialConfidence());
			return new Decision(config.initialConfidence(), expectedRegret,
					validationEffort(validationWork, winnerExecutionCost, comparisonCount,
							config.initialConfidence()),
					instability, expectedRegret <= config.maximumExpectedRegret(), "initial-confidence");
		}

		double[] tiers = confidenceTiers();
		Decision best = null;
		for (double confidence : tiers) {
			double expectedRegret = baseRegret * (1.0d - confidence);
			if (expectedRegret > config.maximumExpectedRegret()) {
				continue;
			}
			double effort = validationEffort(validationWork, winnerExecutionCost, comparisonCount, confidence);
			double loss = effort + expectedRegret;
			if (best == null || loss < best.totalDecisionLoss()) {
				best = new Decision(confidence, expectedRegret, effort, instability, true,
						"posterior-loss-minimum");
			}
		}
		if (best != null) {
			return best;
		}
		double confidence = config.maximumConfidence();
		double expectedRegret = baseRegret * (1.0d - confidence);
		return new Decision(confidence, expectedRegret,
				validationEffort(validationWork, winnerExecutionCost, comparisonCount, confidence), instability,
				false, "regret-budget-requires-replan");
	}

	private double posteriorExpectedRegret(AuditPosterior local) {
		long localCount = local == null ? 0L : local.auditCount;
		double localRegret = local == null ? 0.0d : local.realizedRegret;
		long otherCount = Math.max(0L, globalAuditCount - localCount);
		double otherRegret = Math.max(0.0d, globalRealizedRegret - localRegret);
		double parentMean = (otherRegret + JEFFREYS_PRIOR_EXPECTED_REGRET)
				/ (otherCount + JEFFREYS_PRIOR_MASS);
		double parentPrecision = Math.sqrt(otherCount + JEFFREYS_PRIOR_MASS);
		return (localRegret + parentMean * parentPrecision) / (localCount + parentPrecision);
	}

	private double posteriorInstability(AuditPosterior local) {
		long localCount = local == null ? 0L : local.auditCount;
		long localStable = local == null ? 0L : local.stableCount;
		long otherCount = Math.max(0L, globalAuditCount - localCount);
		long otherStable = Math.max(0L, globalStableCount - localStable);
		double parentInstability = (otherCount - otherStable + 0.5d) / (otherCount + 1.0d);
		double parentPrecision = Math.sqrt(otherCount + 1.0d);
		double localFlips = localCount - localStable;
		return (localFlips + parentInstability * parentPrecision) / (localCount + parentPrecision);
	}

	private double[] confidenceTiers() {
		double[] candidates = Arrays.copyOf(STANDARD_CONFIDENCE_TIERS, STANDARD_CONFIDENCE_TIERS.length + 3);
		candidates[STANDARD_CONFIDENCE_TIERS.length] = config.minimumConfidence();
		candidates[STANDARD_CONFIDENCE_TIERS.length + 1] = config.initialConfidence();
		candidates[STANDARD_CONFIDENCE_TIERS.length + 2] = config.maximumConfidence();
		Arrays.sort(candidates);
		double[] tiers = new double[candidates.length];
		int size = 0;
		for (double candidate : candidates) {
			if (candidate < config.minimumConfidence() || candidate > config.maximumConfidence()) {
				continue;
			}
			if (size == 0 || Double.compare(candidate, tiers[size - 1]) != 0) {
				tiers[size++] = candidate;
			}
		}
		return Arrays.copyOf(tiers, size);
	}

	private static double validationEffort(double validationWork, double winnerExecutionCost, int comparisonCount,
			double confidence) {
		double familyAlpha = (1.0d - confidence) / comparisonCount;
		double informationRatio = Math.log(1.0d / familyAlpha) / Math.log(100.0d);
		return validationWork / winnerExecutionCost * informationRatio;
	}

	public record Config(double initialConfidence, double minimumConfidence, double maximumConfidence,
			double maximumExpectedRegret) {

		public static Config defaults() {
			return new Config(0.99d, 0.51d, 0.999d, 0.01d);
		}

		public Config {
			if (!probability(initialConfidence)
					|| !probability(minimumConfidence)
					|| !probability(maximumConfidence)
					|| minimumConfidence > initialConfidence
					|| initialConfidence > maximumConfidence) {
				throw new IllegalArgumentException("Frontier confidence bounds are inconsistent");
			}
			if (!Double.isFinite(maximumExpectedRegret)
					|| maximumExpectedRegret < 0.0d
					|| maximumExpectedRegret > 1.0d) {
				throw new IllegalArgumentException("Frontier expected-regret budget must be in [0, 1]");
			}
		}

		private static boolean probability(double value) {
			return Double.isFinite(value) && value > 0.0d && value < 1.0d;
		}
	}

	public record Decision(double confidence, double expectedRegret, double validationWork,
			double posteriorInstability, boolean certified, String reason) {

		private double totalDecisionLoss() {
			return validationWork + expectedRegret;
		}
	}

	private record AuditIdentity(long familyFingerprint, long auditIdentity, int auditLane) {
	}

	private static final class AuditPosterior {
		private long auditCount;
		private long stableCount;
		private double realizedRegret;
	}
}
